      ]
    },
    {
      "id": "claudinite-growth",
      "version": "60824.1"
    },
    {
      "id": "tidy-repo",
      "version": "60824.1"
    },
    {
      "id": "html",
      "version": "60822.1"
    },
    {
      "id": "product-wiki",
      "version": "60824.1",
      "answers": {
        "product": "A static commercial website for Missing Bulb. It boasts about our projects, all of them in GitHub. We also do software, management, and AI consulting (and also AI Software Management consulting).",
        "users": "People interested in the services of a software consultancy firm, about AI, about software development life cycle. and people who are interested in the projects that we build in Missing Bulb. It's hard to define because the audience is wide, so make sure you don't research the entire world.",
        "market": "Software, management, and AI consulting — including AI Software Management consulting. Competitor set not yet named."
      }
    },
    "local/session-tooling",
    "local/site-copy",
    "local/repo-mechanics",
    {
      "id": "claude-code-web-users-support",
      "version": "60823.1",
      "config": {
        "repo": "missingbulb/Shepherd"
      }
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60824.3"
    }
  ],
  "taskScheduler": {
    "agenticTaskInvocationEndpoints": {
      "default": {
        "url": "[REDACTED:env:ANTHROPIC_BASE_URL]/v1/claude_code/routines/trig_01BY8uYbgbuBzPwjGK4X4V9y/fire",
        "tokenSecret": "CCR_ROUTINE_TOKEN"
      }
    },
    "dailyHour": 4,
    "weeklyDay": "Sun",
    "monthlyDay": 1
  },
  "engineVersion": "60823.1"
}

// This repo's own pack for how the site gets built and shipped — where the
// release/CI plumbing comes from, and what happens to the steps in a change
// that only the owner can perform. Prose only: both rules are judgment calls
// made while planning a change, not shapes a check over repo state can see
// (the canon's own packs already check the plumbing once it is adopted).
//
// Seeded 2026-08-02 by the grow_with_claudinite growth-extract pass over
// PRs #12, #31, #39 and issues #38, #40.
export default {
  id: 'repo-mechanics',
  ruleRoutingGuidance: {
    belongs:
      "this repo's release/CI plumbing, the owner-only setup steps, and how work is recorded and delivered — issues, PRs, commit messages",
    excludes: 'site markup and copy — html and site-copy; session tooling traps — session-tooling',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  seededByDefault: false,
  worldRules: [],
  workRules: [],
};

// This repo's own pack for how a session's TOOLING behaves here — the traps that
// cost a working session a retry or a wrong answer to the owner, and that no file
// in the tree would have warned about. Prose only: every rule here is about what
// an agent does at runtime, which no check over repo state can observe.
//
// Seeded 2026-07-30 by the grow_with_claudinite conversation-extract pass over
// the captured adoption session; new rules arrive the same way.
export default {
  id: 'session-tooling',
  ruleRoutingGuidance: {
    belongs: 'traps in the session tooling itself — fetching remote content, discovering available tools',
    excludes: 'anything about this repo content — site markup is html, research is product-wiki',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  seededByDefault: false,
  worldRules: [],
  workRules: [],
};

// This repo's own pack for the site's user-facing copy — claims made on the
// marketing pages (privacy, disclosures, "what we do/don't do" statements)
// staying accurate to what the site actually does. Prose only: whether a claim
// still matches the shipped behavior is a judgment call, not something a check
// over markup or code shape can verify.
//
// Seeded 2026-08-01 by the grow_with_claudinite growth-extract pass over PR #20.
export default {
  id: 'site-copy',
  ruleRoutingGuidance: {
    belongs: 'user-facing claims on the site (privacy page, footer disclosures, "what we do" copy) staying true to shipped behavior',
    excludes: 'markup/accessibility mechanics — html; CI and deploy mechanics — github-actions',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  seededByDefault: false,
  worldRules: [],
  workRules: [],
};

// claudinite-growth task: prose-to-checks-sweep — mine a repo's EXISTING pack
// prose for always-testable rules the conversion missed and convert the strongest
// ones (per-project-scheduling redesign). A per-repo task: every repo declaring the
// growth pack sweeps its OWN packs. Which pack paths it works is a config setting,
// `pack_paths`, defaulting to the repo's own local packs; Claudinite itself sets it
// to ALSO include its core `packs/` (projects are not expected to improve core canon
// packs — only Claudinite does). The method is owned by the prose-to-checks skill.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The repo's own capture surface — a consumer improves only its LOCAL packs.
const DEFAULT_PACK_PATHS = ['.claudinite/local/packs'];

export default {
  id: 'prose-to-checks-sweep',
  frequency: 'weekly',                   // works the STANDING backlog a slice at a time — see the cadence note below
  precondition_signals: [],              // the backlog is standing prose, not a windowed signal
  agent_model: 'opus',                   // judging convertibility and authoring checks + fixtures is heavy judgment
  expected_outcome: 'open-pr',           // converts prose to checks in an owner-approved PR (a check can break CI, so it's reviewed)
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,         // reading the packs + authoring a check with fixtures — generous bound

  // WEEKLY, not daily. Freshly written prose no longer waits for this task at all:
  // growth-extract runs the prose-to-checks skill over its OWN additions as the last
  // step of every capture run, so a convertible rule is converted the night it is
  // learned. What is left here is the standing backlog — prose that has already
  // survived at least one upgrade pass — and that set changes on a weekly clock, not
  // a daily one. Daily re-read the same dry corpus with an opus dispatch and an
  // owner-gated PR nobody was waiting on.
  precondition(_signals, config) {
    const paths = Array.isArray(config?.pack_paths) && config.pack_paths.length ? config.pack_paths : DEFAULT_PACK_PATHS;
    return {
      run: true,
      reason: `weekly prose-to-checks backlog sweep over ${paths.join(', ')} (no-ops cheaply when dry)`,
      context: [`Pack paths to sweep (work ONLY these; never a read-only mounted canon pack under .claudinite/shared/): ${paths.join(', ')}.`],
    };
  },
};

