1	// THE CONTINUATION OF A DEAD EXECUTOR RUN (tasks-dispatch DESIGN §10, S36).
2	//
3	// A run that dies — crash, timeout, cancellation, runner loss — never reaches its
4	// own re-dispatch, so without this the queue would sit until the next scheduled
5	// tick. The platform runs the calling job on a FRESH runner after any such death,
6	// and this fires that dispatch instead: the remainder drains in ~a minute, while
7	// the dead run's OWN item waits for the executing leash to reclaim it — nothing
8	// here touches that item.
9	//
10	// `continuation_depth` is the stop. A run that dies at startup — a broken engine,
11	// a revoked token — dies identically every time, and an unguarded continuation
12	// would dispatch itself for as long as that lasts. After MAX_DEPTH the chain
13	// stops and SAYS SO on the repo's workflow-failure issue: a queue that has quietly
14	// stopped draining is the one failure nothing else here would surface, since every
15	// individual run looks like an ordinary death.
16	
17	import { pathToFileURL } from 'node:url';
18	import { makeGh, actionRepoContext, EXECUTOR_WORKFLOW_FILE } from '../signals/gh.mjs';
19	import { dispatchWorkflow } from '../github.mjs';
20	import { reportWorkflowFailure, runUrl } from './workflow-failure.mjs';
21	
22	export const MAX_DEPTH = 3;
23	
24	export const CHAIN_FAILURE_TITLE = 'Claudinite executor chain failed repeatedly';
25	
26	// An absent, empty or unparseable depth is depth 0 — the first death in a chain.
27	// It must never read as a large number, which would silence the continuation
28	// exactly when the queue most needs it.
29	export const nextDepth = (raw) => {
30	  const n = Number(String(raw ?? '').trim());
31	  return (Number.isFinite(n) && n > 0 ? Math.floor(n) : 0) + 1;
32	};
33	
34	// The decision, separated from the CLI shell so it tests against a fake `gh`.
35	// Resolves to the continuation it made; throws when the chain is over, which is
36	// what turns the calling job red.
37	export async function continueOrEscalate(gh, repo, defaultBranch, depth) {
38	  if (depth <= MAX_DEPTH) {
39	    const { ok, status } = await dispatchWorkflow(gh, repo, EXECUTOR_WORKFLOW_FILE, defaultBranch,
40	      { continuation_depth: String(depth) });
41	    if (!ok) throw new Error(`could not continue the chain on ${defaultBranch}: ${status}`);
